"use client";

/**
 * Captions: burned-in captions for short vertical and landscape videos.
 * "phrase" shows two or three words at a time, each popping on as it is said
 * with the current word in the primary colour. "line" shows a full line and
 * fills it word by word. Both sit inside the safe area on a soft backdrop, so they read
 * over any picture.
 *
 * Written by Better Design.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, shiftHue, springs, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["600", "800"], subsets: ["latin"] });

/** One word of the transcript and the frame it is said on. */
export interface SpokenWord {
  word: string;
  frame: number;
}

export interface CaptionsProps {
  /** The transcript in order, each word with the frame it is said on. */
  transcript?: SpokenWord[];
  /** "phrase": a few words at a time, popping on. "line": a full line that fills as it is said. */
  look?: "phrase" | "line";
  placement?: "lower" | "middle";
  /** The picture under the captions. Without one, a theme-coloured placeholder is drawn. */
  picture?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const SAMPLE = "You can make a short launch video in one afternoon, and it will still look like your product.";
const DEFAULT_TRANSCRIPT: SpokenWord[] = SAMPLE.split(" ").map((word, i) => ({ word, frame: 6 + i * 7 + (i > 9 ? 6 : 0) }));

/** Break the transcript into phrases of at most `size` words, ending early at punctuation or a pause. */
function phrasesOf(transcript: SpokenWord[], size: number, pause: number): SpokenWord[][] {
  const phrases: SpokenWord[][] = [[]];
  transcript.forEach((spoken, i) => {
    const phrase = phrases[phrases.length - 1];
    phrase.push(spoken);
    const after = transcript[i + 1];
    if (!after) return;
    const breaks = phrase.length >= size || /[.!?,]$/.test(spoken.word) || after.frame - spoken.frame > pause;
    if (breaks) phrases.push([]);
  });
  return phrases.filter((phrase) => phrase.length > 0);
}

/** Burned-in captions, a phrase or a full line at a time, kept inside the safe area. */
export function Captions({
  transcript = DEFAULT_TRANSCRIPT,
  look = "phrase",
  placement = "lower",
  picture,
  theme: themeOverride,
  font,
}: CaptionsProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const family = pickFont(font, theme, INTER);

  const short = Math.min(width, height);
  const portrait = height > width;
  const fontSize = Math.round(short * (look === "phrase" ? 0.078 : 0.054));
  const groups = phrasesOf(transcript, look === "phrase" ? 3 : portrait ? 4 : 7, 14);
  const spoken = transcript.filter((w) => w.frame <= frame).length - 1;
  // The group holding the last word said; before the first word, nothing shows.
  const groupIndex = groups.findIndex((g) => g.some((w) => w === transcript[spoken]));
  const group = groupIndex >= 0 ? groups[groupIndex] : undefined;
  const groupStart = group?.[0]?.frame ?? 0;
  const boxIn = easings.out(progress(frame, groupStart, 6));

  const anchor = placement === "middle" ? { top: 0, bottom: 0, alignItems: "center" } : { bottom: height * 0.12, alignItems: "flex-end" };

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family }}>
      {picture ? <Img src={picture} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <Placeholder theme={theme} />}
      <div style={{ position: "absolute", left: width * 0.08, right: width * 0.08, display: "flex", justifyContent: "center", ...anchor }}>
        {group ? (
          <div
            key={groupIndex}
            style={{
              display: "flex",
              flexWrap: "wrap",
              justifyContent: "center",
              columnGap: "0.28em",
              maxWidth: "100%",
              padding: "0.32em 0.6em 0.38em",
              borderRadius: theme.radius * 2,
              background: withAlpha(theme.background, 0.82),
              boxShadow: `0 0.4em 1.4em ${withAlpha(theme.foreground, 0.12)}`,
              fontSize,
              fontWeight: look === "phrase" ? 800 : 600,
              letterSpacing: "-0.02em",
              lineHeight: 1.18,
              textAlign: "center",
              opacity: look === "line" ? boxIn : 1,
              transform: look === "line" ? `translateY(${(1 - boxIn) * 10}px)` : undefined,
            }}
          >
            {group.map((word) => {
              const index = transcript.indexOf(word);
              const next = transcript[index + 1];
              const isCurrent = index === spoken;
              if (look === "phrase") {
                const s = spring({ frame: frame - word.frame, fps, config: springs.bouncy });
                if (frame < word.frame) return null;
                return (
                  <span
                    key={index}
                    style={{
                      display: "inline-block",
                      color: isCurrent ? theme.primary : theme.foreground,
                      transform: `scale(${0.55 + 0.45 * s})`,
                    }}
                  >
                    {word.word}
                  </span>
                );
              }
              const end = next && next.frame - word.frame < 30 ? next.frame : word.frame + 8;
              const fill = progress(frame, word.frame, Math.max(1, end - word.frame));
              return (
                <span key={index} style={{ position: "relative", display: "inline-block" }}>
                  <span style={{ color: withAlpha(theme.foreground, 0.32) }}>{word.word}</span>
                  <span style={{ position: "absolute", left: 0, top: 0, color: isCurrent ? theme.primary : theme.foreground, clipPath: `inset(-0.2em ${(1 - fill) * 100}% -0.2em 0)`, whiteSpace: "nowrap" }}>
                    {word.word}
                  </span>
                </span>
              );
            })}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
}

/** A soft gradient scene with a few blurred shapes, standing in for footage. */
function Placeholder({ theme }: { theme: VideoTheme }) {
  const blob = (color: string, alpha: number) => `radial-gradient(closest-side, ${withAlpha(color, alpha)}, ${withAlpha(color, 0)})`;
  return (
    <AbsoluteFill style={{ background: theme.background, overflow: "hidden" }}>
      <div style={{ position: "absolute", width: "75%", aspectRatio: "1", left: "-20%", top: "-25%", background: blob(theme.primary, 0.45) }} />
      <div style={{ position: "absolute", width: "65%", aspectRatio: "1", right: "-18%", bottom: "-20%", background: blob(shiftHue(theme.primary, 45), 0.4) }} />
      <div style={{ position: "absolute", width: "45%", aspectRatio: "1", right: "10%", top: "-10%", background: blob(shiftHue(theme.primary, -40), 0.3) }} />
    </AbsoluteFill>
  );
}
